function germanText(value){
 const tokens=String(value??'').split(/([\p{L}\p{M}\p{N}_]+)/u);
 return `<span class="german-text">${tokens.map(token=>{const article=token.toLocaleLowerCase('de-DE');return ['der','die','das'].includes(article)?`<span class="article article-${article}">${escape(token)}</span>`:escape(token);}).join('')}</span>`;
}
