function animateIn(selector,kind='forward'){
 if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 document.querySelectorAll(selector).forEach((el,i)=>el.animate?.([
  {opacity:0,transform:kind==='back'?'translateX(-14px)':kind==='question'?'translateX(20px)':kind==='set'?'translateY(12px) scale(.98)':'translateY(12px)'},
  {opacity:1,transform:'none'}
 ],{duration:kind==='set'?320:240,delay:i*25,easing:'cubic-bezier(.22,.68,.2,1)',fill:'backwards'}));
}
function paintScreen(html,key,kind='forward'){
 const previous=lastPaintKey;root.innerHTML=html;lastPaintKey=key;
 if(previous===key)return;
 const question=key.startsWith('question:')&&previous.split(':').slice(0,3).join(':')===key.split(':').slice(0,3).join(':');
 animateIn(question?'.test-card, .test-options':key.startsWith('flash:')?'.flash-scene':'.page-content, .session',question?'question':kind);
}
