function toast(text){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3300);}
function stat(id){return progress.words[id]||{correct:0,wrong:0,match:0,test:0};}
function counts(){return Object.fromEntries(Object.entries(progress.words).map(([id,w])=>[id,w.match||0]));}
function favorite(id){return progress.favorites.includes(id);}
function todayCount(){return progress.days[dayKey()]||0;}
function known(){return DATA.words.filter(w=>stat(w.id).match>=15).length;}
function studied(){return DATA.words.filter(w=>stat(w.id).correct+stat(w.id).wrong>0).length;}
function catPct(id){const words=DATA.words.filter(w=>w.category===id);return Math.round(words.filter(w=>stat(w.id).match>=15).length/words.length*100);}
let audioCtx;
function sound(ok){if(!progress.settings.sound)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(ok?660:220,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(ok?990:150,audioCtx.currentTime+.13);g.gain.setValueAtTime(.05,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.2);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.2);}catch{}}
