function partForLesson(lesson){return parts.find(p=>p.lessons.some(l=>l.id===lesson?.id));}
function courseState(){return curriculumState(lessons,progress);}
function adjacentLesson(l,direction=1){return l?lessons[lessons.indexOf(l)+direction]||null:null;}
function rememberSet(l){lastSets[activeCourse]=l.id;try{localStorage.setItem('wortatlas-last-sets',JSON.stringify(lastSets));}catch{}}
function isUnlocked(lesson){return !!lesson&&courseState().byId.get(lesson.id)?.unlocked===true;}
function allowedWordIds(){return new Set(courseState().entries.filter(e=>e.unlocked).flatMap(e=>e.lesson.ids));}
function setTitle(l){return `${byCategory.get(l.category).title} · Set ${l.setNumber}`;}
function pathSelection(){
 const state=courseState(),current=state.current;
 let part=parts.find(p=>p.id===pathSource)||parts.find(p=>p.units.some(u=>u.id===pathUnit))||partForLesson(current);
 if(!groupProgress(part,state).unlocked)part=partForLesson(current);
 let unit=part.units.find(u=>u.id===pathUnit&&groupProgress(u,state).unlocked);
 if(!unit)unit=part.units.find(u=>groupProgress(u,state).unlocked&&!groupProgress(u,state).complete)||part.units[0];
 pathSource=part.id;pathUnit=unit.id;return {part,unit,state};
}
function reviewWords(){return poolFor('all').filter(w=>progress.ratings?.[w.id]!=='known'&&(progress.ratings?.[w.id]==='repeat'||progress.ratings?.[w.id]==='unsure'||stat(w.id).wrong>0)).sort((a,b)=>({repeat:0,unsure:1}[progress.ratings?.[a.id]]??2)-({repeat:0,unsure:1}[progress.ratings?.[b.id]]??2));}
function home(){const recent=lastSets[activeCourse],last=lessons.find(l=>l.id===recent);return courseHome({parts,state:courseState(),icon,sync:syncBadge(),reviewCount:reviewWords().length,savedCount:poolFor('saved').length,recent:last&&isUnlocked(last)?{id:last.id,title:setTitle(last)}:null});}
function pathPage(){const selected=pathSelection(),html=coursePath({...selected,icon,words:DATA.words,recent:lastSets[activeCourse]})+offlineUnitButton();recentCompletedSet=null;return html;}
