function topics(){return `<section class="word-topic-browser"><header class="workspace-heading"><div><span class="eyebrow">TESTDAF · KELİMELER</span><h1>Konunu seç, çalışmaya başla.</h1><p>${DATA.categories.length} konu. İstediğin konunun tüm kelimelerini birlikte çalış.</p></div></header><div class="word-topic-list">${DATA.categories.map(c=>`<button class="word-topic-choice" data-action="category" data-id="${c.id}"><img src="./illustrations/topics/${c.id.replace('.','-')}.webp" width="96" height="72" alt="" loading="lazy"><span><strong>${escape(c.title)}</strong><span lang="de">${escape(c.de)}</span><small>${c.count} kelime</small></span>${icon('arrow')}</button>`).join('')}</div></section>`;}

function collectionPool(){const allowed=allowedWordIds();return DATA.words.filter(w=>allowed.has(w.id)&&studyAvailable(w)&&(view!=='saved'||favorite(w.id))&&(!category||category==='all'||w.category===category));}
function currentWords(){let list=collectionPool();if(wordFilter==='new')list=list.filter(w=>!stat(w.id).correct&&!stat(w.id).wrong&&!progress.ratings?.[w.id]);if(wordFilter==='difficult')list=list.filter(w=>stat(w.id).wrong>0);if(wordFilter==='mastered')list=list.filter(w=>stat(w.id).match>=15);if(['known','unsure','repeat'].includes(wordFilter))list=list.filter(w=>progress.ratings?.[w.id]===wordFilter);if(query){const q=normalize(query);list=list.filter(w=>normalize(w.de+' '+w.tr+' '+w.topic).includes(q));}if(sort==='alpha')list=[...list].sort((a,b)=>a.de.localeCompare(b.de,'de'));return list;}
function collectionChips(){const pool=collectionPool(),r=ratingSummary(pool.map(w=>w.id),progress.ratings);return [['all','Tümü',pool.length],['known','Biliyorum',r.known],['unsure','Kararsızım',r.unsure],['repeat','Tekrar',r.repeat],['difficult','Hata yaptıklarım',pool.filter(w=>stat(w.id).wrong>0).length],['new','Yeni',pool.filter(w=>!stat(w.id).correct&&!stat(w.id).wrong&&!progress.ratings?.[w.id]).length]].map(([id,label,count])=>`<button class="filter-chip filter-${id} ${wordFilter===id?'selected':''}" data-action="word-chip" data-id="${id}" aria-pressed="${wordFilter===id}">${label}<span>${fmt(count)}</span></button>`).join('');}
