function emptyState(saved=false){return `<div class="empty workspace-empty"><span class="empty-art">${icon(saved?'bookmark':'search')}</span><span class="eyebrow">${saved?'SANA ÖZEL BİR KOLEKSİYON':'KELİMELER BURADA'}</span><h3>${saved?'İlk kelimeni kaydet.':'Biraz farklı arayalım.'}</h3><p>${saved?'Bir kelimenin yanındaki yer imine dokun. Tekrar görmek istediklerin burada toplansın.':'Bu arama ve filtrelerle eşleşen kelime yok. Farklı bir kelime yazabilir veya filtreleri temizleyebilirsin.'}</p><button class="secondary" data-action="${saved?'nav':'clear-filters'}" data-view="words">${saved?'Kelimeleri keşfet':'Filtreleri temizle'} ${icon('arrow')}</button></div>`;}
function listResults(){const list=currentWords();return `<div class="list-count">${fmt(list.length)} kelime ve ifade ${query?'bulundu':''} <span class="muted">· ${sort==='source'?'Kaynak sırası':'Alfabetik sıra'}</span></div>${list.length?`<div class="word-list">${wordRows(list.slice(0,visible))}</div>${list.length>visible?`<button class="secondary more" data-action="more">40 kelime daha göster ${icon('arrow')}</button>`:''}`:emptyState(view==='saved'&&!poolFor('saved').length)}`;}
function collection(){const isSaved=view==='saved',c=view==='category'?byCategory.get(category):null,saved=poolFor('saved').length,availableCategories=new Set(poolFor('all').map(w=>w.category));return `<section class="collection-page">${c?`<button class="back-link" data-action="nav" data-view="words">${icon('back')} Tüm konular</button><header class="workspace-heading"><div><span class="eyebrow">${courseLabel()} · KELİMELER</span><h1>${escape(c.title)}</h1><p>${escape(c.de)} · ${c.count} kelime ve ifade</p></div>${categorySymbol(c,DATA.categories.indexOf(c))}</header>`:`<header class="workspace-heading"><div><span class="eyebrow">KELİME ATÖLYEN</span><h1>${isSaved?'Bir daha bakalım.':'Kelimelerin, bir arada.'}</h1><p>${isSaved?'Kaydettiklerini hatırla, öğrendiklerini yanında taşı.':'Bul, keşfet ve tekrar etmek istediklerini seç.'}</p></div><span class="heading-symbol">${icon(isSaved?'bookmark':'book')}</span></header>`}${isSaved&&saved?`<div class="saved-study-banner"><span class="saved-stack">${icon('cards')}</span><div><strong>${fmt(saved)} kelime seni bekliyor</strong><p>Kaydettiklerinle kısa bir kart turu yap.</p></div><button class="primary" data-action="setup" data-mode="flash" data-category="saved">Kartları aç ${icon('arrow')}</button></div><div class="saved-mode-actions">${[['test','test','Test çöz'],['match','match','Eşleştir'],['write','headphones','Dinle ve yaz']].map(([mode,ico,label])=>`<button class="secondary" data-action="setup" data-mode="${mode}" data-category="saved">${icon(ico)} ${label}</button>`).join('')}</div>`:c?`<div class="category-actions"><button class="primary" data-action="setup" data-mode="flash" data-category="${c.id}">${icon('cards')} Kartlarla çalış</button><button class="secondary" data-action="setup" data-mode="test" data-category="${c.id}">${icon('test')} Test çöz</button><button class="secondary" data-action="setup" data-mode="match" data-category="${c.id}">${icon('match')} Eşleştir</button><button class="secondary" data-action="setup" data-mode="write" data-category="${c.id}">${icon('headphones')} Dinle ve yaz</button></div>`:''}<div class="collection-toolbar"><label class="search-field">${icon('search')}<span class="sr-only">Almanca veya Türkçe kelime ara</span><input id="word-search" type="search" placeholder="Almanca veya Türkçe ara…" value="${escape(query)}" autocomplete="off"></label><div class="collection-selects">${!c?`<label><span>Konu</span><select id="category-filter" aria-label="Konu filtresi"><option value="all">Tüm konular</option>${DATA.categories.filter(c=>availableCategories.has(c.id)).map(c=>`<option value="${c.id}" ${category===c.id?'selected':''}>${escape(c.title)}</option>`).join('')}</select></label>`:''}<label><span>Sıralama</span><select id="word-sort" aria-label="Sıralama"><option value="source" ${sort==='source'?'selected':''}>Kaynak sırası</option><option value="alpha" ${sort==='alpha'?'selected':''}>Almanca A–Z</option></select></label></div></div><div id="collection-chips" class="collection-chips" role="group" aria-label="Kelime durumuna göre filtrele">${collectionChips()}</div><div class="collection-caption"><span>${icon('info')} Seçtiğin konunun kelimeleri gösterilir.</span>${!c?`<button class="link-btn" data-action="nav" data-view="topics">Konular ${icon('arrow')}</button>`:''}</div><div id="list-results">${listResults()}</div><div class="article-legend" aria-label="Artikel renkleri"><span><b class="article-der">der</b> mavi</span><span><b class="article-die">die</b> kırmızı</span><span><b class="article-das">das</b> yeşil</span></div></section>`;}
