function openModal(html,extra=''){lastFocus=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${extra}" role="dialog" aria-modal="true" aria-label="${extra==='word-detail'?'Kelime ayrıntısı':extra==='downloads-modal'?'Çevrimdışı bölümler':extra==='settings-modal'?'Ayarlar':'Çalışma ayarları'}" tabindex="-1">${html}</section></div>`;document.body.classList.add('modal-open');modalRoot.querySelector('.modal').focus();}
