function dictationText(value){return String(value??'').normalize('NFC').toLocaleLowerCase('de-DE').replace(/[\p{P}\p{S}]/gu,'').replace(/\s+/g,' ').trim();}
function dictationEquivalent(value,expected){const variants={ä:'(?:ä|ae|a)',ö:'(?:ö|oe|o)',ü:'(?:ü|ue|u)',ß:'(?:ß|ss)'},escapeRegex=ch=>ch.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),pattern=[...dictationText(expected)].map(ch=>variants[ch]||escapeRegex(ch)).join('');return new RegExp(`^${pattern}$`,'u').test(dictationText(value));}
function dictationMatches(value,expected){return dictationText(value)===dictationText(expected)||dictationEquivalent(value,expected);}
function liveDictationMarkup(value,expected){
 const text=[...String(value??'').normalize('NFC')],entered=[],target=[...dictationText(expected)];
 text.forEach((ch,index)=>{if(!/[\p{P}\p{S}]/u.test(ch))entered.push({ch:ch.toLocaleLowerCase('de-DE'),index});});
 const rows=target.length+1,cols=entered.length+1,dp=Array.from({length:rows},()=>Array(cols).fill(0));
 for(let i=0;i<rows;i++)dp[i][0]=i;for(let j=0;j<cols;j++)dp[0][j]=j;
 for(let i=1;i<rows;i++)for(let j=1;j<cols;j++)dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(target[i-1]===entered[j-1].ch?0:1));
 const aligned=new Set();let i=target.length,j=entered.length;
 while(i||j){if(i&&j&&dp[i][j]===dp[i-1][j-1]+(target[i-1]===entered[j-1].ch?0:1)){if(target[i-1]===entered[j-1].ch)aligned.add(entered[j-1].index);i--;j--;}else if(i&&dp[i][j]===dp[i-1][j]+1)i--;else if(j)j--;else break;}
 const complete=dictationMatches(value,expected);let correct=0;
 const html=text.map((ch,index)=>{if(/[\p{P}\p{S}]/u.test(ch))return `<span class="dictation-punctuation">${escape(ch)}</span>`;const match=complete||aligned.has(index);if(match)correct++;return `<span class="${match?'dictation-correct':'dictation-error'}">${escape(ch)}</span>`;}).join('');
 return {html,correct,total:target.length,complete};
}
function speakDictation(slow=false){
 const word=byId.get(session?.ids?.[session.index]);if(!word?.exampleDe)return;
 if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){toast('Bu cihazda sesli okuma kullanılamıyor.');return;}
 window.speechSynthesis.cancel();document.querySelector('.dictation-play')?.classList.remove('is-playing');const utterance=new SpeechSynthesisUtterance(word.exampleDe);utterance.lang='de-DE';utterance.rate=slow?.76:.88;utterance.pitch=1;
 const voices=window.speechSynthesis.getVoices(),germanVoices=voices.filter(v=>v.lang?.toLowerCase().startsWith('de')),voice=germanVoices.find(v=>/natural|premium|enhanced/i.test(v.name))||germanVoices.find(v=>v.lang?.toLowerCase()==='de-de')||germanVoices[0];if(voice)utterance.voice=voice;
 utterance.onstart=()=>document.querySelector('.dictation-play')?.classList.add('is-playing');
 utterance.onend=utterance.onerror=()=>document.querySelector('.dictation-play')?.classList.remove('is-playing');
 window.speechSynthesis.speak(utterance);
}
