async function manageDownload(category,remove=false){
 if(downloading)return;
 downloading=chapterKey(activeCourse,category);const course=activeCourse;showDownloads();
 try{downloads=remove?await removeDownload(account,course,category):await downloadChapter(account,course,category);toast(remove?'Bölüm bu cihazdan kaldırıldı. İlerlemen korundu.':'Bölüm çevrimdışı hazır.');}
 catch(e){toast(e.name==='QuotaExceededError'?'Cihazda yer kalmadı. Kullanmadığın bir indirmeyi kaldır.':'İndirme tamamlanamadı. Bağlantını ve tarayıcı depolama iznini kontrol et.');}
 finally{downloading=null;if(modalRoot.querySelector('.downloads-modal'))showDownloads();if(!session)render();}
}

async function clickAction(e){const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;
 switch(a){
  case 'word-chip':wordFilter=id;visible=40;refreshList();break;
 case 'review-start':config={mode:'flash',scope:'review',target:0,direction:'de-tr',limit:'all'};startSession();break;
 case 'theme':progress.settings.theme=el.dataset.value;cloud?.meta('theme',el.dataset.value);persist();applyTheme();settings();break;
 case 'downloads':showDownloads();break;
 case 'download-chapter':await manageDownload(id);break;
 case 'remove-download':await manageDownload(id,true);break;
 case 'rate-card':rateCard(id,el.dataset.value,el.dataset.full==='true');break;
 case 'focus-set':focusSet();break;
 case 'flash-focus':session.ids=focusIds(session.baseIds||session.ids,progress.ratings);if(!session.ids.length)return;session.index=0;session.flipped=false;session.reviewDone=false;renderFlash();break;
 case 'flash-all':session.ids=[...(session.baseIds||session.ids)];session.index=0;session.flipped=false;session.reviewDone=false;renderFlash();break;
 case 'dictation-play':case 'dictation-replay':speakDictation(false);break;case 'dictation-slow':speakDictation(true);break;case 'dictation-show':answerWritten(true);break;case 'dictation-next':nextWritten();break;
 case 'nav':navigate(el.dataset.view);break;case 'open-part':openPart(id);break;case 'open-unit':openUnit(id);break;case 'unit-picker':showUnitPicker();break;case 'locked':toast(el.dataset.message||'Önce bir önceki seti tamamla.');break;case 'complete-set':completeSet(id||session?.scope||activeSet);break;case 'continue-path':{const {unit}=pathSelection(),next=lessons[unit.lessons.at(-1).number];if(next)openPart(next.source);else navigate('learn');break;}case 'lesson':showLesson(id);break;
 case 'set-start':startSet(el.dataset.mode);break;
 case 'set-flip':setCardFlipped=!setCardFlipped;updateCardFace(el,setCardFlipped,byId.get(setLesson().ids[setCardIndex]));break;
 case 'set-prev':case 'set-next':setCardIndex=Math.max(0,Math.min(setLesson().ids.length-1,setCardIndex+(a==='set-next'?1:-1)));setCardFlipped=false;updateSetPreview(e);break;

 case 'set-share':shareSet();break;
 case 'share-words':await shareWords();break;
 case 'copy-words':await copySetContent(lessonShareText(setLesson(),poolFor(activeSet)));break;
 case 'copy-set-link':await copySetContent(`${location.origin}${location.pathname}#${lessonRoute(setLesson())}`);break;
 case 'back-to-set':{const scope=session.scope;session=null;showLesson(scope);break;}
 case 'next-lesson':{const current=lessons.find(l=>l.id===session?.scope),next=current?adjacentLesson(current):courseState().current;session=null;if(next)showLesson(next.id);else navigate('learn');break;}case 'category':navigate('category',id);break;case 'group':filterGroup=id;render();break;case 'word':showWord(id);break;case 'sync-retry':cloud?.refresh();break;case 'favorite':toggleFavorite(id);break;case 'close':closeModal();break;case 'settings':settings();break;case 'setup':setup(el.dataset.mode,el.dataset.category);break;case 'config':config[el.dataset.key]=el.dataset.value;if(el.dataset.key==='direction')testDirection=el.dataset.value;renderSetup();break;case 'start':startSession();break;case 'resume':resumeMatch();break;case 'match-tile':selectMatch(el,e);break;case 'test-direction':if(session?.mode==='test'){session.autoPaused=true;testDirection=session.direction=session.direction==='de-tr'?'tr-de':'de-tr';nextQuestion();renderTest();}break;case 'pause-next':if(session){session.autoPaused=true;renderTest();}break;case 'test-answer':answerTest(id);break;case 'next-question':nextQuestion();renderTest();window.scrollTo({top:0,behavior:'smooth'});break;case 'exit-session':finishSession();break;case 'end-home':session=null;navigate('learn');break;case 'new-round':{const mode=session.previousMode,scope=session.scope;session=null;if(scope?.startsWith('lesson:')){activeSet=scope;view='set';startSet(mode);}else{render();setup(mode,scope);}break;}case 'flip':if(session?.mode==='flash'){session.flipped=!session.flipped;updateCardFace(el,session.flipped,byId.get(session.ids[session.index]),true);}break;case 'flash-prev':session.index=Math.max(0,session.index-1);session.flipped=false;renderFlash();break;case 'flash-next':if(session.index===session.ids.length-1)session.reviewDone=true;else session.index++;session.flipped=false;renderFlash();break;case 'more':visible+=40;refreshList();break;case 'clear-filters':query='';wordFilter='all';if(view!=='category')category=null;render();break;case 'sound-toggle':progress.settings.sound=!progress.settings.sound;cloud?.meta('sound',progress.settings.sound);persist();el.classList.toggle('on',progress.settings.sound);el.setAttribute('aria-checked',progress.settings.sound);break;case 'export':exportData();break;case 'import':document.querySelector('#import-file').click();break;case 'confirm-import':if(pendingImport){if(cloud)cloud.importProgress(pendingImport);else {progress._favorites||=Object.fromEntries(progress.favorites.map(id=>[id,true]));for(const op of seedOperations(pendingImport))applyOperation(progress,op);}pendingImport=null;persist();closeModal();render();toast('Yedek yüklendi. İlerlemen hazır.');}break;}
}
