document.addEventListener('keydown',e=>{if(!session||modalRoot.children.length||e.ctrlKey||e.metaKey||e.altKey||e.repeat||['INPUT','TEXTAREA','SELECT','A','SUMMARY'].includes(e.target?.tagName))return;if(session.mode==='flash'&&!session.reviewDone){if(e.code==='Space'&&e.target?.tagName!=='BUTTON'){e.preventDefault();session.flipped=!session.flipped;const card=document.querySelector('.flashcard');if(card)updateCardFace(card,session.flipped,byId.get(session.ids[session.index]),true);}else if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')session.index=Math.max(0,session.index-1);else if(session.index===session.ids.length-1)session.reviewDone=true;else session.index++;session.flipped=false;renderFlash();}}else if(['test','learn'].includes(session.mode)){if(!session.answered&&/^[1-4]$/.test(e.key)){e.preventDefault();const o=session.question.options[Number(e.key)-1];if(o)answerTest(o.id);}else if(session.answered&&e.key==='Enter'&&e.target?.tagName!=='BUTTON'){e.preventDefault();nextQuestion();renderTest();window.scrollTo({top:0,behavior:'smooth'});}}});
document.addEventListener('keydown',e=>{const modal=modalRoot.querySelector('.modal');if(!modal)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const list=[...modal.querySelectorAll('button:not(:disabled),a[href],summary,input:not(.hidden),select,[tabindex="0"]')].filter(el=>el.getClientRects().length>0);if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===modal)){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===modal)){e.preventDefault();first.focus();}}});
